  <script>
    (function () {
      'use strict';

      const inputs = document.querySelectorAll('.otp-input');
      const verifyBtn = document.getElementById('verify-btn');
      const timerEl = document.getElementById('timer');
      const countdownContainer = timerEl.parentElement;

      // Convert Arabic-Indic digits to Western digits
      function toWesternDigits(str) {
        return str.replace(/[٠١٢٣٤٥٦٧٨٩]/g, function (c) {
          return c.charCodeAt(0) - 1632;
        });
      }

      // OTP input navigation
      inputs.forEach((input, index) => {
        input.addEventListener('input', function () {
          // Convert Arabic digits to Western
          this.value = toWesternDigits(this.value);
          // Keep only digits
          this.value = this.value.replace(/[^0-9]/g, '');
          if (this.value.length === 1) {
            if (index < inputs.length - 1) {
              inputs[index + 1].focus();
              inputs[index + 1].select();
            }
          }
        });

        input.addEventListener('keydown', function (e) {
          if (e.key === 'Backspace') {
            if (this.value === '' && index > 0) {
              inputs[index - 1].focus();
            }
          }
          if (e.key === 'ArrowRight' && index < inputs.length - 1) {
            inputs[index + 1].focus();
          }
          if (e.key === 'ArrowLeft' && index > 0) {
            inputs[index - 1].focus();
          }
        });

        input.addEventListener('paste', function (e) {
          e.preventDefault();
          const pasted = e.clipboardData.getData('text');
          const converted = toWesternDigits(pasted).replace(/[^0-9]/g, '');
          if (converted.length === 6) {
            inputs.forEach((inp, i) => {
              inp.value = converted[i] || '';
            });
            inputs[5].focus();
          }
        });
      });

      // Verify button handler
      verifyBtn.addEventListener('click', function () {
        const code = Array.from(inputs).map(input => input.value).join('');
        if (code.length !== 6) {
          // Simple visual feedback for incomplete code
          inputs.forEach(input => {
            input.style.borderColor = '#f44336';
            setTimeout(() => {
              input.style.borderColor = '';
            }, 1000);
          });
          return;
        }
        // Simulate verification
        this.textContent = '...';
        this.disabled = true;
        setTimeout(() => {
          alert('الرمز تم التحقق منه بنجاح: ' + code);
          this.textContent = 'IR';
          this.disabled = false;
        }, 1000);
      });

      // Countdown logic
      let timeLeft = 45;
      let countdownInterval = null;

      function formatTime(seconds) {
        const mins = Math.floor(seconds / 60);
        const secs = seconds % 60;
        return `${mins}:${secs.toString().padStart(2, '0')}`;
      }

      function startCountdown() {
        timeLeft = 45;
        timerEl.textContent = formatTime(timeLeft);
        timerEl.dir = 'ltr';

        countdownInterval = setInterval(() => {
          timeLeft--;
          if (timeLeft >= 0) {
            timerEl.textContent = formatTime(timeLeft);
          }
          if (timeLeft <= 0) {
            clearInterval(countdownInterval);
            showResendButton();
          }
        }, 1000);
      }

      function showResendButton() {
        countdownContainer.innerHTML = '';
        const resendBtn = document.createElement('button');
        resendBtn.className = 'resend-btn';
        resendBtn.textContent = 'أعد الإرسال';
        resendBtn.addEventListener('click', function () {
          // Reset inputs
          inputs.forEach(input => input.value = '');
          inputs[0].focus();
          // Restart countdown
          countdownContainer.innerHTML = 'إعادة إرسال بعد <span id="timer" dir="ltr">0:45</span>';
          timerEl = document.getElementById('timer');
          startCountdown();
        });
        countdownContainer.appendChild(resendBtn);
      }

      // Initialize countdown
      startCountdown();
    })();
  </script>
